package org.opengridseg.ui;
import ij.ImagePlus;import ij.gui.*;import ij.process.FloatProcessor;import java.awt.Color;import java.awt.Font;import java.util.Arrays;import java.util.List;import org.opengridseg.detect.*;import org.opengridseg.image.FloatPlane;
public final class PreviewRenderer {private static final Color[] COLORS={new Color(230,40,40),new Color(20,130,220),new Color(20,170,80),new Color(190,120,20)};private PreviewRenderer(){}public static ImagePlus create(String fov,DetectionResult result,List<ArraySelection> selections){FloatPlane p=result.rotated().plane();ImagePlus image=new ImagePlus("OpenGridSeg — "+fov+" — horizontal BF preview",new FloatProcessor(p.width(),p.height(),p.pixels().clone()));setDisplay(image,p);Overlay overlay=new Overlay();Pitch pitch=result.pitch();GridPhase phase=result.phase();for(ArraySelection selection:selections){if(!selection.enabled())continue;Color color=COLORS[selection.id()%COLORS.length];double x0=phase.xOffset()+selection.colStart()*pitch.x()-pitch.x()/2,y0=phase.yOffset()+selection.rowStart()*pitch.y()-pitch.y()/2;Roi box=new Roi((int)Math.round(x0),(int)Math.round(y0),(int)Math.round(20*pitch.x()),(int)Math.round(20*pitch.y()));box.setStrokeColor(color);box.setStrokeWidth(2);overlay.add(box);TextRoi label=new TextRoi(x0+8,y0+8,"A"+selection.id()+"  "+selection.source().observedCount()+" direct",new Font(Font.SANS_SERIF,Font.BOLD,16));label.setStrokeColor(color);overlay.add(label);for(int r=0;r<20;r++)for(int c=0;c<20;c++){double x=phase.xOffset()+(selection.colStart()+c)*pitch.x(),y=phase.yOffset()+(selection.rowStart()+r)*pitch.y();OvalRoi point=new OvalRoi(x-2.5,y-2.5,5,5);point.setStrokeColor(color);overlay.add(point);}}image.setOverlay(overlay);return image;}private static void setDisplay(ImagePlus image,FloatPlane p){float[] sample=new float[(p.pixels().length+63)/64];int n=0;for(int i=0;i<p.pixels().length;i+=64)if(Float.isFinite(p.pixels()[i]))sample[n++]=p.pixels()[i];Arrays.sort(sample,0,n);if(n>0)image.setDisplayRange(sample[(int)(0.01*(n-1))],sample[(int)(0.99*(n-1))]);}private static double[] toDoubleSample(float[] p){return new double[0];}}
